let raw = $json.output ?? $json.text ?? '';
let data = null;

const toText = (v) => {
  if (v === undefined || v === null) return '';
  if (typeof v === 'string') return v;
  try { return JSON.stringify(v); } catch { return String(v); }
};

raw = toText(raw)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// 1) intento parse directo
try { data = JSON.parse(raw); } catch (_) {}

// 2) extraer bloque JSON dentro de texto mixto
if (!data) {
  const first = raw.indexOf('{');
  const last  = raw.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { data = JSON.parse(raw.slice(first, last + 1)); } catch (_) {}
  }
}

// 3) fallback: texto plano sin JSON — tomar solo el último párrafo
// para evitar enviar razonamiento interno al cliente
if (!data || typeof data !== 'object') {
  let replyText = raw;
  const parts = raw.split(/\n\n+/);
  if (parts.length > 1) {
    const lastMeaningful = parts.filter(p => p.trim().length > 0).pop();
    if (lastMeaningful && lastMeaningful.trim().length > 10) {
      replyText = lastMeaningful.trim();
    }
  }
  data = {
    subagente_codigo: null,
    reply_text: replyText || 'Gracias por tu mensaje. Enseguida te ayudo.',
    accion_tipo: 'ninguna',
    accion_requerida: false,
    accion_payload: null,
    escalar_humano: false,
    motivo_humano: null,
    confianza: 0
  };
}

// Sanitizar reply_text
let texto = toText(data.reply_text).replace(/\\n/g, '\n').trim();
texto = texto.replace(/\n{3,}/g, '\n\n');
texto = texto.replace(/["\\]+(?=\*)/g, '').replace(/(?<=\*)["\\]+/g, '');
if (!texto) texto = 'Gracias por tu mensaje. Enseguida te ayudo.';
if (texto.length > 4000) texto = texto.slice(0, 3900) + '\n\n... (mensaje recortado)';

// Leer Parsear2 con protección — n8n 2.12 puede fallar la referencia en merges
let p2 = {};
try { p2 = $('Parsear4').first().json ?? {}; } catch (_) { p2 = {}; }

const instanceObj = p2.instance ?? {};

return [{
  json: {
    mensaje: texto,
    meta: {
      subagente: data.subagente_codigo || null,
      estado:    data.accion_tipo      || null,
      confianza: Number(data.confianza || 0)
    },
    control: {
      requiere_accion: data.accion_requerida === true,
      accion_tipo:     data.accion_tipo     || null,
      accion_payload:  data.accion_payload  || null,
      escalar_humano:  data.escalar_humano  === true,
      motivo_humano:   data.motivo_humano   || null
    },
    config: {
      subagente_codigo:  p2.subagente_codigo  || data.subagente_codigo || null,
      motivo:            p2.motivo            || null,
      requiere_humano:   false,
      silencio_bot:      false,
      content:           p2.content           || null,
      instance_name:     instanceObj.name     || null,
      instance_apikey:   instanceObj.apikey   || null,
      external_thread_id: p2.external_thread_id || null,
    }
  }
}];

