// Toma el item actual y, si existe, el item de Normalizar
const current = $input.first()?.json ?? {};
const normalizar = $('Normalizar').first()?.json ?? {};

// helpers
const clean = (v) => {
  if (v === undefined || v === null) return undefined;
  const s = String(v).trim();
  return s === '' ? undefined : s;
};

const asIntIfNumeric = (v) => {
  if (v === undefined || v === null) return undefined;
  const s = String(v).trim();
  if (!/^\d+$/.test(s)) return undefined;
  return Number(s);
};

// prioridad de fuentes (Normalizar -> item actual)
const canalUserId =
  clean(normalizar?.contact?.numero) ||
  clean(normalizar?.message?.from) ||
  clean(current?.contact?.numero) ||
  clean(current?.message?.from);

const payload = {
  canal: 'whatsapp',
  canal_user_id: canalUserId,
  historial_limite: 10,
  memoria_limite: 8,
};

// idconv opcional, si lo tienes en alguna rama
const idconv =
  clean(current?.data?.idconv) ||
  clean(current?.idconv) ||
  clean(normalizar?.chat?.idconv) ||
  clean(normalizar?.idconv);

if (idconv) payload.idconv = idconv;

// trigger_idmsg solo si es id interno numérico
const triggerIdMsg =
  asIntIfNumeric(current?.data?.idmsg) ??
  asIntIfNumeric(current?.trigger_idmsg) ??
  asIntIfNumeric(normalizar?.chat?.idmsg);

if (triggerIdMsg !== undefined) payload.trigger_idmsg = triggerIdMsg;

// external_message_id sí puede ser el id externo de WhatsApp
const externalMessageId =
  clean(normalizar?.message?.id) ||
  clean(current?.message?.id) ||
  clean(current?.external_message_id);

if (externalMessageId) payload.external_message_id = externalMessageId;

// si no hay nada para resolver conversación, corta limpio
if (!payload.canal_user_id && !payload.idconv && !payload.external_message_id) {
  return [
    {
      json: {
        _skip_context: true,
        reason: 'Sin identificadores para contexto',
        debug: {
          from_normalizar_numero: normalizar?.contact?.numero ?? null,
          from_normalizar_message_from: normalizar?.message?.from ?? null,
          from_current_data_idconv: current?.data?.idconv ?? null,
          from_normalizar_message_id: normalizar?.message?.id ?? null,
        }
      }
    }
  ];
}

return [{ json: payload }];

